#include <bits/stdc++.h>
using namespace std;
#define MODUL 1000000007
typedef unsigned long long ull_t;

struct Mat {
    ull_t mat[35][35];
    int size;
    friend Mat operator*(const Mat &a, const Mat &b) {
        Mat c;
        c.size = a.size;
        for (int i = 0; i < a.size; ++i) {
            for (int j = 0; j < a.size; ++j) {
                c.mat[i][j] = 0;
                for (int k = 0; k < a.size; ++k) {
                    c.mat[i][j] += a.mat[i][k] * b.mat[k][j];
                }
                c.mat[i][j] %= MODUL;
            }
        }
        return c;
    }
};

int main() {
    ull_t n, m;
    cin >> n >> m;
    Mat A, I;
    A.size = m + 1;
    for (int i = 0; i <= m; ++i) {
        A.mat[i][i] = 1;
        A.mat[0][i] = 1;
    }
    I.size = m + 1;
    for (int i = 0; i <= m; ++i) {
        I.mat[i][i] = 1;
    }

    ull_t y_factor = 1, y_power = 1, level = 0, sum = 0;
    while (y_power * m <= n) {
        y_power *= m;
        ++level;
    }

    vector<vector<Mat>> bi_m(level + 1, vector<Mat>(m + 1));
    for (int t = 0; t <= level; ++t) {
        if (t > 0) {
            bi_m[t][0] = bi_m[t - 1][0];
            for (int i = 1; i <= m; ++i) {
                bi_m[t][0] = bi_m[t][0] * bi_m[t - 1][i];
            }
        }
        for (int i = 1; i <= m; ++i) {
            bi_m[t][i] = bi_m[t][i - 1];
            for (int j = m - 2; j >= 0; --j) {
                for (int k = 0; k <= m; ++k) {
                    swap(bi_m[t][i].mat[j][k], bi_m[t][i].mat[j + 1][k]);
                }
            }
            for (int j = m - 2; j >= 0; --j) {
                for (int k = 0; k <= m; ++k) {
                    swap(bi_m[t][i].mat[k][j], bi_m[t][i].mat[k][j + 1]);
                }
            }
        }
    }

    Mat res = I;
    while (sum < n) {
        if (sum + y_power <= n) {
            sum += y_power;
            res = res * bi_m[level][0];
            y_factor = (y_factor + 1) % m;
        } else {
            y_power /= m;
            --level;
        }
    }

    ull_t answ = 0;
    for (int i = 0; i <= m; ++i) {
        answ = (answ + res.mat[i][m]) % MODUL;
    }
    cout << answ << "\n";
}
